  "landing.one.s7": "התקדמות",
  "landing.faq.title": "פרהקוהנטלי אסקהד שאלות",
  "landing.faq.q1": "הוא Second Brain ג׳וסט צ׳אטבוט?",
  "landing.faq.a1": "אין. שלו פהרסונאל למידה הנוירונמהנט: זה ונדהרסטאנדס שלך תוכן, טיצ׳הס זה, ו רהמהמבהרס ההתקדמות שלך מעל זמן.",
  "landing.faq.q2": "אפשר אני וורק עם סהוהראל פדפס ו מסמכים?",
  "landing.faq.a2": "כן. אפשר גראופ פדפס, פוטוס, סקאנס ו הערות אל והולה מקצוע ו ללמוד מ מלא סהט, לא סינגלה קובץ.",
  "landing.faq.q3": "מה אפשר אני לעשות עם AI פרופהססור?",
  "landing.faq.a3": "גהט טאוגהט, אסק עבור הקספלאנאציוןס, דיסקוסס, רונ מודרך מפגשים ו פראקטיסה עם תרגילים — אדאפטהד אל שלך רמה.",
  "landing.faq.q4": "אפשר אני טאלק אל AI פרופהססור אוט לאוד?",
  "landing.faq.a4": "כן. ספוקהנ קונוהרסאציון, וראל תרגילים ו וראל בחינות להט את/ה פראקטיסה אוט לאוד.",
  "landing.faq.q5": "מה הוא תאום דיגיטלי?",
  "landing.faq.a5": "פהרסונאליזהד זיכרון של שלך למידה — מה את/ה להבין, מאסטהר, פורגהט ו יימ עבור.",
  "landing.faq.q6": "איך לעשות זיכרון ו חזרה וורק?",
  "landing.faq.a6": "ספאקהד-רהפהטיציון הנגינה (FSRS) סצ׳הדולהס חזרות ב ריגהט מומהנט סו את/ה רהטיינ עוד עם פחות הפפורט.",
  "landing.faq.q7": "אפשר אני וסה Second Brain עבור שלי אקאדהמיק וורק?",
  "landing.faq.a7": "כן. מרחב עבודה אקדמי גוידהס לאבס, הומהוורק, דוחות ו עוד — טיצ׳ינג מהתוד, לא ג׳וסט תשובה.",
  "landing.faq.q8": "איך עושה שפה למידה וורק?",
  "landing.faq.a8": "יממהרסיונ, קונוהרסאציון, וראל תרגול ו שאדווינג — ו עזרה ונדהרסטאנדינג שפה של שלך וונ קורריקולומ.",
  "landing.faq.q9": "איך הוא שלי נתונים פרוטהקטהד?",
  "landing.faq.a9": "שלך למידה נתונים פווהרס שלך הקספהריהנקה. את/ה קונטרול החשבון שלך ו אפשר ניהול שלך נתונים מ הפרופיל שלך.",
