  "landing12.hero.scene.next.context": "סיבה ויסיבלה · דהסטינאציון פרהסהרוהד",
  "landing12.story.kicker": "אחד פרודוקט, אחד הקספהריהנקה",
  "landing12.story.title": "ואטצ׳ קנוולהדגה מווה דרך והולה סיסטהמ",
  "landing12.story.lead": "מקור אינו עצירה ב אחסון. זה דהמונסטראציון פוללווס אותו הקשר מ מסמך אל ונדהרסטאנדינג, תרגול, חזרה ו אקאדהמיק פרודוקציון.",
  "landing12.story.documents.title": "מסמך בהקומהס וסאבלה קנוולהדגה",
  "landing12.story.documents.short": "מסמכים",
  "landing12.story.documents.desc": "ספרייה רהקהיוהס מקור. מסמך ינטהלליגהנקה רידס זה, הקסטראקטס מושגים ו פרהפארהס גראונדהד שאלות ללא ינוהנטינג התקדמות.",
  "landing12.story.brain.title": "מושגים ג׳וינ קוננהקטהד קוגניטיוה מאפ",
  "landing12.story.brain.short": "המוח שלי",
  "landing12.story.brain.desc": "קוגניטיוה טוינ מאקהס מושגים, רהלאציוןשיפס, חוזקות ו פראגיליטיהס ויסיבלה. זה ציבורי דוגמה הוא יללוסטראטיוה, לא ריל לומד סקורה.",
  "landing12.story.professor.title": "פרופהססור טיצ׳הס מ אותו הקשר",
  "landing12.story.professor.short": "פרופסור בינה מלאכותית",
  "landing12.story.professor.desc": "מסמך, טארגהט מושג ו למידה מטרה פוללוו מפגש. הקספהריהנקה ניתןקומה הסבר, שיעור, שאלה או מודרך תרגול.",
  "landing12.story.oral.title": "ונדהרסטאנדינג בהקומהס ספוקהנ תרגול",
  "landing12.story.oral.short": "וראל & קול",
  "landing12.story.oral.desc": "מקשיב, תמלול ו תשובה הם דיסטינקט, רידאבלה סטאטהס. תמליל רהמיינס ויסיבלה; אין דהקוראטיוה ואוהפורמ פרהטהנדס אל מיסורה ספיצ׳.",
  "landing12.story.review.title": "שברירי ידי בהקומהס חזרה",
  "landing12.story.review.short": "חזרה",
  "landing12.story.review.desc": "חזרה הנגינה קונסולידאטהס קנוולהדגה ב ריגהט זמן. תאריך שוונ ההרה הוא הקספליקיטלי דהמונסטראציון, לא ריל לוח זמנים.",
  "landing12.story.workspace.title": "קנוולהדגה בהקומהס פרודוקציון",
  "landing12.story.workspace.short": "מרחב עבודה",
  "landing12.story.workspace.desc": "מרחב עבודה אקדמי קיפס תוכנית, טקסט, מקורות ו ציטוטים טוגהתהר בזמן קונטהקסטואל אססיסטאנט סופפורטס לומדים וונ וורק.",
  "landing12.story.sharedContext": "שארהד הקשר",
  "landing12.story.traceability": "מקור טראקיביליטי",
  "landing12.story.outcome": "אני גיוה מידע → Second Brain ונדהרסטאנדס זה → טיצ׳הס לי → ההלפס לי פראקטיסה → ההלפס לי רהמהמבהר → ההלפס לי וסה זה.",
  "landing12.story.nba": "אז זה פרופוסהס ניקוי, הקספליינאבלה הבא פעולה במקום ליוינג לי ב דאשבוארד.",
