  "landing12.story.professor.answer": "להט לנו רהבוילד זה מ אטפ: ראשון פורפוסה, אז שלבים, אז שורט בדיקה ב שלך וונ וורדס.",
  "landing12.story.professor.session": "הקספהריהנקה מפגש קיפס מקור, ינטהנציון, היסטוריה ו הבא פעולה טוגהתהר.",
