  "landing12.story.oral.transcriptText": "“קהללולאר רהספיראציון טורנס הנהרגי ב גלוקוסה אל אטפ קהלל אפשר וסה.”",
  "landing12.story.oral.note": "קול קומפלהמהנטס וריטטהנ הקספהריהנקה. נכשל שמע סהרויקה לעולם לא רהמווהס רידאבלה תוכן.",
