  "landing12.pricing.title": "שלושה ינדיוידואל ופפהרס, ללא ינוהנטהד פרטים",
  "landing12.pricing.lead": "דהפיניטיוה פריקהס, קווטאס ו בהנהפיטס יהיה להיות דהקידהד אחרי ציבורי בהטא. לאנדינג רק פרהסהנטס ריל קאטאלוג היום.",
  "landing12.pricing.free.name": "חינם",
  "landing12.pricing.free.desc": "דהפאולט ינדיוידואל ופפהר עבור דיסקווהרינג Second Brain הקספהריהנקה.",
  "landing12.pricing.pro.name": "פרו",
  "landing12.pricing.pro.desc": "מתקדם ינדיוידואל ופפהר והוסה פינאל פריקה, קווטאס ו בהנהפיטס רהמיינ אל להיות קונפיגורהד.",
  "landing12.pricing.max.name": "מאקס",
  "landing12.pricing.max.desc": "רוב הקסטהנסיוה ינדיוידואל ופפהר; שלו פינאל קוממהרקיאל פרטים רהמיינ אל להיות קונפיגורהד.",
  "landing12.pricing.freeStatus": "חינם ופפהר זמין",
  "landing12.pricing.pending": "פרטים אחרי ציבורי בהטא",
  "landing12.pricing.sourceNote": "אותהנטיקאטהד מינוי סקרינס רהמיינ נתונים-דריוהנ מ באקהנד. אין פריקה, דיסקאונט, מכסה או הקסקלוסיוה בהנהפיט הוא הארד-קודהד ההרה.",
  "landing12.faq.kicker": "וסהפול תשובות",
  "landing12.faq.title": "שאלות? אנחנו תשובה אותם.",
  "landing12.faq.lead": "שורט תשובות על מה פרודוקט ריללי עושה היום.",
  "landing12.faq.q1": "מה הוא Second Brain?",
  "landing12.faq.a1": "פהרסונאל ינטהלליגהנט למידה סיסטהמ הזה קוננהקטס שאלות, מקורות, טיצ׳ינג, תרגול, זיכרון ו אקאדהמיק וורק ב אחד הקשר.",
  "landing12.faq.q2": "הוא זה סימפלי צ׳אטבוט?",
  "landing12.faq.a2": "אין. קונוהרסאציון הוא אחד ממשק. אותו מפגש ניתןקומה שיעור, וראל תרגיל, סאורקהד מסמך שאלה, חזרה או מרחב עבודה פעולה.",
  "landing12.faq.q3": "איך עושה המוח שלי וורק?",
  "landing12.faq.a3": "זה מאקהס שלך מושגים, רהלאציוןשיפס, שליטה ראיות, זיכרון ו למידה היסטוריה ויסיבלה. זה אדאפטס שלו תצוגה אל מאטוריטי של זמין נתונים.",
  "landing12.faq.q4": "אפשר אני וסה שלי וונ מסמכים?",
  "landing12.faq.a4": "כן. ספרייה אקקהפטס נתמך קבצים ו סקאנס, הקספוסהס ריל מעבד סטאטהס, הקסטראקטס מושגים ו סופפורטס גראונדהד שאלות ו טראנספורמאציוןס.",
  "landing12.faq.q5": "אפשר אני ללמוד שפה?",
  "landing12.faq.a5": "כן. ריל ליפה שפה הנגינה קומבינהס קהפר קורריקולומ, הקספליקיט שפה וורק, וורלד מיססיונס, וראל תרגול, טארגהטהד רהפייר, חזרה ו אפשר-לעשות ראיות.",
  "landing12.faq.q6": "איך עושה AI פרופהססור וורק?",
  "landing12.faq.a6": "זה וסהס פעיל לומד הקשר ו אפשר הסבר, טיצ׳, שאלה, אססהסס או פראקטיסה בזמן פרהסהרוינג הקספהריהנקה מפגש.",
  "landing12.faq.q7": "איך לעשות חזרות וורק?",
  "landing12.faq.a7": "חזרה וסהס אקטואל היסטוריה ו חזרה מרווחת אל פריוריטיזה קנוולהדגה הזה ריסקס בהינג פורגוטטהנ. נונ-AI חזרה רהמיינס זמין ב־דהפהנדהנטלי של AI קווטאס.",
  "landing12.faq.q8": "איזה שפות הם זמין?",
  "landing12.faq.a8": "המאגר המשותף כולל כעת 34 שפות לימוד. שפת הממשק ושפת הלימוד נשארות תמיד בחירות נפרדות.",
  "landing12.faq.q9": "עושה מחקר חיפוש אינטרנט?",
  "landing12.faq.a9": "מחקר אפשר וורק אקרוסס המוח שלי ו הספרייה שלך היום. הקסטהרנאל אינטרנט ספק אינו קונפיגורהד ב נוכחי דהפלוימהנט, סו לאנדינג אינו קליימ הזה זה הוא.",
  "landing12.faq.q10": "הם שלי נתונים פרטי?",
  "landing12.faq.a10": "אותהנטיקאטהד קונטרולס קווהר AI זיכרון, מסמכים, קונסהנטס, ייצוא ו חשבון דהלהציון. זה עמוד אינו להוסיף להגאל או ינפראסטרוקטורה פרומיסהס בהיונד האלה קונטרולס.",
  "landing12.faq.q11": "מה הוא דיפפהרהנקה בין חינם, פרו ו מאקס?",
  "landing12.faq.a11": "הם הם שלושה ינדיוידואל תוכנית להוהלס ב באקהנד קאטאלוג. פינאל פריקהס, קווטאס ו תוכנית בהנהפיטס יהיה להיות קונפיגורהד אחרי ציבורי בהטא.",
  "landing12.faq.q12": "היכן אפשר אני וסה Second Brain?",
  "landing12.faq.a12": "אינטרנט הקספהריהנקה הוא זמין ב־ זה יישום. Android ו iOS הם טהצ׳ניקאללי פרהפארהד ללא ציבורי סטורה לינקס; Windows ו macOS דיסטריבוציון הוא עדיין ופקומינג.",
